def segs(g):
    h,w=len(g),len(g[0]); bg=max(Counter(x for r in g for x in r).items(), key=lambda t:t[1])[0]
    seen=set(); res=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]
                while stack:
                    p=stack.pop()
                    if p in seen: continue
                    seen.add(p); rr,cc=p
                    # follow down-right
                    nr,nc=rr+1,cc+1
                    while nr<h and nc<w and g[nr][nc]==col:
                        stack.append((nr,nc))
                        nr+=1; nc+=1
                pts=sorted(stack)
                if len(pts)>1 or pts==[(r,c)] and g[rr][cc]!=bg:
                    res.append((col,min(pts),max(pts)))
    return res
